import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [activeTab, setActiveTab] = useState('upload');
  const [drugList, setDrugList] = useState([
    { id: 1, name: '硝苯地平缓释片', spec: '5mg', manufacturer: 'XX制药厂', expiryDate: '2026-12-31' },
    { id: 2, name: '二甲双胍片', spec: '0.5g', manufacturer: 'YY制药厂', expiryDate: '2026-06-30' }
  ]);
  const [imagePreview, setImagePreview] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [explanation, setExplanation] = useState(null);
  const [conflicts, setConflicts] = useState([
    {
      level: 'high',
      drugs: '硝苯地平缓释片 + 西地那非',
      explanation: '这两个药一起吃会伤肝，可能导致严重的低血压，绝对不要一起服用！'
    },
    {
      level: 'medium',
      drugs: '硝苯地平缓释片 + 西柚汁',
      explanation: '西柚汁会影响药物代谢，建议间隔4小时以上服用。'
    }
  ]);
  const [reminders, setReminders] = useState([
    { id: 1, time: '08:00', drug: '硝苯地平缓释片', taken: false },
    { id: 2, time: '12:00', drug: '二甲双胍片', taken: true },
    { id: 3, time: '20:00', drug: '硝苯地平缓释片', taken: false }
  ]);
  const [isListening, setIsListening] = useState(false);
  const [manualDrugName, setManualDrugName] = useState('');
  const [manualSpec, setManualSpec] = useState('');

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImagePreview(e.target.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setImagePreview(e.target.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const startVoiceRecognition = () => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      const recognition = new SpeechRecognition();
      recognition.lang = 'zh-CN';
      recognition.continuous = false;
      recognition.interimResults = false;

      recognition.onstart = () => {
        setIsListening(true);
      };

      recognition.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        alert('您说的是：' + transcript);
        setIsListening(false);
      };

      recognition.onerror = (event) => {
        console.error('语音识别错误:', event.error);
        setIsListening(false);
        alert('语音识别失败，请重试');
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognition.start();
    } else {
      alert('您的浏览器不支持语音识别功能');
    }
  };

  const speak = (text) => {
    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = 'zh-CN';
      utterance.rate = 0.8;
      utterance.volume = 1;
      window.speechSynthesis.speak(utterance);
    } else {
      alert('您的浏览器不支持语音播报功能');
    }
  };

  const analyzeImage = () => {
    setIsLoading(true);
    setTimeout(() => {
      const newDrug = {
        id: Date.now(),
        name: '硝苯地平缓释片(Ⅰ)',
        spec: '5mg',
        manufacturer: 'XX制药厂',
        expiryDate: '2026-12-31'
      };
      setDrugList([...drugList, newDrug]);
      setExplanation({
        title: '👨‍⚕️ 用药说明',
        content: '这药一天吃两次，早饭晚饭后各一片。每片5毫克，您需要吃半片。绝对不能喝酒！可能会犯困，别开车。'
      });
      setIsLoading(false);
      setActiveTab('explanation');
    }, 2000);
  };

  const addManualDrug = () => {
    if (manualDrugName) {
      const newDrug = {
        id: Date.now(),
        name: manualDrugName,
        spec: manualSpec || '请补充规格',
        manufacturer: '请补充厂家',
        expiryDate: '请补充效期'
      };
      setDrugList([...drugList, newDrug]);
      setManualDrugName('');
      setManualSpec('');
      alert('药品添加成功！');
    }
  };

  const markAsTaken = (id) => {
    setReminders(reminders.map(r => 
      r.id === id ? { ...r, taken: true } : r
    ));
  };

  const renderUploadTab = () => (
    <div className="card">
      <h2 className="card-title">📷 上传药品照片</h2>
      <div 
        className="upload-area" 
        onClick={() => document.getElementById('file-input').click()}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
      >
        <input
          id="file-input"
          type="file"
          accept="image/*"
          style={{ display: 'none' }}
          onChange={handleFileUpload}
        />
        <div className="upload-icon">💊</div>
        <p className="upload-text">拍张药盒照片传上来，剩下的我帮您看</p>
        <p className="upload-hint">点击或拖拽图片到这里</p>
      </div>

      {imagePreview && (
        <img src={imagePreview} alt="药品预览" className="preview-image" />
      )}

      <div className="btn-group">
        <button 
          className="btn btn-primary" 
          onClick={analyzeImage}
          disabled={!imagePreview || isLoading}
        >
          🔍 开始识别
        </button>
        <button 
          className="btn btn-secondary" 
          onClick={startVoiceRecognition}
        >
          🎤 语音说药名
        </button>
      </div>

      {isListening && (
        <div className="loading">正在听您说话...</div>
      )}

      {isLoading && (
        <div className="loading">正在分析药品，请稍候...</div>
      )}

      <div style={{ marginTop: '40px' }}>
        <h2 className="card-title">✍️ 手动输入药品</h2>
        <div className="input-section">
          <label className="input-label">药品名称</label>
          <input
            type="text"
            className="text-input"
            placeholder="请输入药品名称"
            value={manualDrugName}
            onChange={(e) => setManualDrugName(e.target.value)}
          />
        </div>
        <div className="input-section">
          <label className="input-label">规格</label>
          <input
            type="text"
            className="text-input"
            placeholder="例如：5mg"
            value={manualSpec}
            onChange={(e) => setManualSpec(e.target.value)}
          />
        </div>
        <button className="btn btn-success" onClick={addManualDrug}>
          ➕ 添加药品
        </button>
      </div>
    </div>
  );

  const renderExplanationTab = () => (
    <div className="card">
      <h2 className="card-title">📖 用药说明</h2>
      {explanation ? (
        <>
          <div className="explanation-box">
            <h3 className="explanation-title">{explanation.title}</h3>
            <p className="explanation-text">{explanation.content}</p>
          </div>
          <div className="warning-box">
            <h4 className="warning-title">⚠️ 重要提醒</h4>
            <p className="warning-text">以上内容仅供参考，请务必遵循医嘱！</p>
          </div>
          <div className="btn-group">
            <button className="btn btn-primary" onClick={() => speak(explanation.content)}>
              🔊 播放语音
            </button>
            <button className="btn btn-success" onClick={() => setActiveTab('drugs')}>
              💊 查看药箱
            </button>
          </div>
        </>
      ) : (
        <p style={{ fontSize: '20px', color: '#666' }}>请先上传药品照片获取用药说明</p>
      )}
    </div>
  );

  const renderConflictTab = () => (
    <div className="card">
      <h2 className="card-title">⚠️ 冲突检测</h2>
      {conflicts.length > 0 ? (
        conflicts.map((conflict, index) => (
          <div key={index} className={`conflict-item conflict-level-${conflict.level}`}>
            <h4 style={{ fontSize: '22px', fontWeight: 'bold', marginBottom: '12px' }}>
              {conflict.level === 'high' ? '🔴 严重冲突' : conflict.level === 'medium' ? '🟡 中等冲突' : '🔵 轻微冲突'}
            </h4>
            <p style={{ fontSize: '20px', marginBottom: '8px', fontWeight: '600' }}>
              {conflict.drugs}
            </p>
            <p style={{ fontSize: '18px', color: '#333' }}>{conflict.explanation}</p>
          </div>
        ))
      ) : (
        <p style={{ fontSize: '20px', color: '#27ae60' }}>✅ 未发现冲突，用药安全！</p>
      )}
      <div className="btn-group">
        <button className="btn btn-primary" onClick={() => speak('检测到以下用药冲突：' + conflicts.map(c => c.explanation).join('；'))}>
          🔊 播放冲突说明
        </button>
      </div>
    </div>
  );

  const renderDrugsTab = () => (
    <div className="card">
      <h2 className="card-title">🏠 家庭药箱</h2>
      {drugList.length > 0 ? (
        <div className="drug-list">
          {drugList.map(drug => (
            <div key={drug.id} className="drug-card">
              <h4 className="drug-name">{drug.name}</h4>
              <p className="drug-info">规格：{drug.spec}</p>
              <p className="drug-info">生产厂家：{drug.manufacturer}</p>
              <p className="drug-info">有效期至：{drug.expiryDate}</p>
            </div>
          ))}
        </div>
      ) : (
        <p style={{ fontSize: '20px', color: '#666' }}>药箱是空的，请先添加药品</p>
      )}
      <div className="btn-group">
        <button className="btn btn-primary" onClick={() => setActiveTab('upload')}>
          ➕ 添加药品
        </button>
        <button className="btn btn-secondary" onClick={() => setActiveTab('conflict')}>
          🔍 检测冲突
        </button>
      </div>
    </div>
  );

  const renderCalendarTab = () => {
    const today = new Date();
    const days = [];
    const dayNames = ['日', '一', '二', '三', '四', '五', '六'];

    for (let i = 0; i < 14; i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      days.push({
        date: date,
        dayNumber: date.getDate(),
        dayName: dayNames[date.getDay()],
        isToday: i === 0
      });
    }

    return (
      <div className="card">
        <h2 className="card-title">📅 用药日历</h2>
        <div className="calendar-grid">
          {days.map((day, index) => (
            <div key={index} className={`calendar-day ${day.isToday ? 'today' : ''}`}>
              <div className="calendar-day-number">{day.dayNumber}</div>
              <div className="calendar-day-name">周{day.dayName}</div>
            </div>
          ))}
        </div>

        <h3 style={{ fontSize: '24px', fontWeight: 'bold', margin: '30px 0 20px 0', color: '#667eea' }}>
          ⏰ 今日提醒
        </h3>
        {reminders.map(reminder => (
          <div key={reminder.id} className="reminder-item">
            <div>
              <div className="reminder-time">{reminder.time}</div>
              <div className="reminder-drug">{reminder.drug}</div>
            </div>
            {reminder.taken ? (
              <span style={{ fontSize: '20px', color: '#27ae60', fontWeight: 'bold' }}>✅ 已服药</span>
            ) : (
              <button className="btn btn-success" onClick={() => markAsTaken(reminder.id)}>
                ✓ 我吃了
              </button>
            )}
          </div>
        ))}
      </div>
    );
  };

  const renderEmergencyTab = () => (
    <div className="card">
      <h2 className="card-title">🚨 紧急助手</h2>

      <button 
        className="emergency-btn"
        onClick={() => window.location.href = 'tel:120'}
      >
        <span className="emergency-icon">🆘</span>
        紧急呼叫120
      </button>

      <div style={{ marginTop: '30px' }}>
        <h3 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '20px', color: '#667eea' }}>
          💬 快速咨询
        </h3>
        <div className="input-section">
          <label className="input-label">描述您的症状或问题</label>
          <textarea
            className="text-input"
            placeholder="例如：血压突然180怎么办？"
            rows="4"
            style={{ resize: 'none' }}
          />
        </div>
        <button className="btn btn-primary">
          🤖 咨询AI助手
        </button>
      </div>

      <div style={{ marginTop: '30px' }}>
        <h3 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '20px', color: '#667eea' }}>
          📞 紧急联系人
        </h3>
        <div className="drug-card" style={{ cursor: 'pointer' }} onClick={() => window.location.href = 'tel:13800138000'}>
          <h4 className="drug-name">👨 子女 - 张三</h4>
          <p className="drug-info">电话：138-0013-8000</p>
        </div>
      </div>
    </div>
  );

  return (
    <div className="app-container">
      <header className="header">
        <h1>👨‍⚕️ AI 智能药剂师</h1>
        <p>您身边贴心的用药安全小助手</p>
      </header>

      <div className="main-content">
        <div className="nav-tabs">
          <button 
            className={`nav-tab ${activeTab === 'upload' ? 'active' : ''}`}
            onClick={() => setActiveTab('upload')}
          >
            📷 识别药品
          </button>
          <button 
            className={`nav-tab ${activeTab === 'explanation' ? 'active' : ''}`}
            onClick={() => setActiveTab('explanation')}
          >
            📖 用药说明
          </button>
          <button 
            className={`nav-tab ${activeTab === 'conflict' ? 'active' : ''}`}
            onClick={() => setActiveTab('conflict')}
          >
            ⚠️ 冲突检测
          </button>
          <button 
            className={`nav-tab ${activeTab === 'drugs' ? 'active' : ''}`}
            onClick={() => setActiveTab('drugs')}
          >
            🏠 家庭药箱
          </button>
          <button 
            className={`nav-tab ${activeTab === 'calendar' ? 'active' : ''}`}
            onClick={() => setActiveTab('calendar')}
          >
            📅 用药日历
          </button>
          <button 
            className={`nav-tab ${activeTab === 'emergency' ? 'active' : ''}`}
            onClick={() => setActiveTab('emergency')}
          >
            🚨 紧急助手
          </button>
        </div>

        {activeTab === 'upload' && renderUploadTab()}
        {activeTab === 'explanation' && renderExplanationTab()}
        {activeTab === 'conflict' && renderConflictTab()}
        {activeTab === 'drugs' && renderDrugsTab()}
        {activeTab === 'calendar' && renderCalendarTab()}
        {activeTab === 'emergency' && renderEmergencyTab()}
      </div>
    </div>
  );
}

export default App;
